#include <string>
#include <sstream>

std::string toHtml(const std::string& text) {
    std::stringstream ss;
    bool inside_em = false;
    for (char c : text) {
        switch (c) {
            case '<':
                ss << "&lt;";
                break;
            case '>':
                ss << "&gt;";
                break;
            case '&':
                ss << "&amp;";
                break;
            case '"':
                ss << "&quot;";
                break;
            case '\'':
                ss << "&apos;";
                break;
            case '/':
                if (inside_em) {
                    ss << c;
                } else {
                    ss << "&frasl;";
                }
                break;
            case '*':
                if (inside_em) {
                    ss << c;
                } else {
                    ss << "<em>";
                    inside_em = true;
                }
                break;
            case '_':
                if (inside_em) {
                    ss << c;
                } else {
                    ss << "<strong>";
                }
                break;
            case '{':
                ss << "<code>";
                break;
            case '}':
                ss << "</code>";
                break;
            default:
                ss << c;
                break;
        }
    }
    if (inside_em) {
        ss << "</em>";
    }
    return ss.str();
}
```

